import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, listJobs, submitJob, toJob } from './jobs.ts';
import {
  checkIdempotencyKey,
  isJsonContentType,
  parseSubmissionBody,
  type FieldError,
} from './validation.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3_000;
/** Largest request body accepted. A valid submission is well under this. */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalidRequest(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', `Invalid request: ${fields.map((f) => f.field).join(', ')}.`, fields);
}

class BodyTooLarge extends Error {}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new BodyTooLarge());
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const keyError = checkIdempotencyKey(req.headers['idempotency-key']);
  if (keyError) fields.push(keyError);
  const idempotencyKey = keyError ? undefined : (req.headers['idempotency-key'] as string | undefined);

  let rawBody: string | undefined;
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    try {
      rawBody = await readBody(req);
    } catch (e) {
      if (e instanceof BodyTooLarge) {
        fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
      } else {
        throw e;
      }
    }
  }

  let parsed: ReturnType<typeof parseSubmissionBody> | undefined;
  if (rawBody !== undefined) {
    parsed = parseSubmissionBody(rawBody);
    if (!parsed.ok) fields.push(...parsed.fields);
  }

  if (fields.length > 0 || !parsed || !parsed.ok) {
    return invalidRequest(res, fields.length > 0 ? fields : [{ field: 'body', message: 'is invalid' }]);
  }

  const result = submitJob(db, parsed.value, idempotencyKey);
  if (result.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
  }
  send(res, result.kind === 'created' ? 201 : 200, result.job);
}

function healthRoute(_req: IncomingMessage, res: ServerResponse): void {
  const row = db.prepare('SELECT last_seen_ms FROM worker_heartbeat WHERE id = 1').get() as
    | { last_seen_ms: number }
    | undefined;
  const up = row !== undefined && Date.now() - row.last_seen_ms <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function pageRoute(_req: IncomingMessage, res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

function listJobsRoute(_req: IncomingMessage, res: ServerResponse): void {
  send(res, 200, { jobs: listJobs(db) });
}

function getJobRoute(_req: IncomingMessage, res: ServerResponse, params: string[]): void {
  let id: string;
  try {
    id = decodeURIComponent(params[0]!);
  } catch {
    return sendError(res, 404, 'not_found', 'No such job.');
  }
  const job = getJob(db, id);
  if (!job) return sendError(res, 404, 'not_found', 'No such job.');
  send(res, 200, toJob(db.prepare('SELECT 1').get() ? (job as never) : (job as never)));
}

type Handler = (req: IncomingMessage, res: ServerResponse, params: string[]) => void | Promise<void>;

const ROUTES: Array<{ pattern: RegExp; methods: Record<string, Handler> }> = [
  { pattern: /^\/health$/, methods: { GET: healthRoute } },
  { pattern: /^\/$/, methods: { GET: pageRoute } },
  { pattern: /^\/api\/jobs$/, methods: { GET: listJobsRoute, POST: createJobRoute } },
  { pattern: /^\/api\/jobs\/([^/]+)$/, methods: { GET: getJobRoute } },
];

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  for (const r of ROUTES) {
    const match = r.pattern.exec(pathname);
    if (!match) continue;
    const handler = r.methods[method];
    if (!handler) {
      const allow = Object.keys(r.methods).join(', ');
      return sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined) ||
        void res.setHeader('allow', allow);
    }
    return void (await handler(req, res, match.slice(1)));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

